/* @lc app=leetcode id=3620 lang=kotlin */ class Solution { fun ok(n: Int, g: Map<Int, List<IntArray>>, topo: List<Int>, online: BooleanArray, k: Long, x: Int): Boolean = LongArray(n) { Long.MAX_VALUE / 4 }.also { dist -> dist[0] = 0L }.also { dist -> topo.forEach { u -> if (dist[u] < Long.MAX_VALUE / 4 && online[u]) g[u].orEmpty().filter { it[2] >= x && online[it[1]] && dist[u] + it[2] < dist[it[1]] }.forEach { dist[it[1]] = dist[u] + it[2] } } }[n - 1] <= k fun findMaxPathScore(edges: Array<IntArray>, online: BooleanArray, k: Long): Int = online.size.let { n -> edges.groupBy { it[0] }.let { g -> IntArray(n).also { d -> edges.forEach { d[it[1]]++ } }.let { d -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.flatMap { u -> g[u].orEmpty().filter { --d[it[1]] == 0 }.map { it[1] } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { topo -> if (!ok(n, g, topo, online, k, 0)) -1 else generateSequence(0 to 1_000_000_000) { (lo, hi) -> if (lo >= hi) null else ((lo + hi + 1) / 2).let { mid -> if (ok(n, g, topo, online, k, mid)) mid to hi else lo to mid - 1 } }.last().first } } } } }